import React, { useState, useEffect } from 'react';
import './HeroSection.css';

const HeroSection = ({ onCatalogClick }) => {
  const [currentSlide, setCurrentSlide] = useState(0);
  
  const phoneNumber = '+79991234567';

  const slides = [
    { image: process.env.PUBLIC_URL + '/images/hero/0.png' },
    { image: process.env.PUBLIC_URL + '/images/hero/1.png' },
    { image: process.env.PUBLIC_URL + '/images/hero/2.png' },
    { image: process.env.PUBLIC_URL + '/images/hero/3.png' },
    { image: process.env.PUBLIC_URL + '/images/hero/4.png' },
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length);
    }, 4000);
    return () => clearInterval(timer);
  }, [slides.length]);

  const goToSlide = (index) => {
    setCurrentSlide(index);
  };

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + slides.length) % slides.length);
  };

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % slides.length);
  };

  const goToHome = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setTimeout(() => {
      window.location.reload();
    }, 300);
  };

  return (
    <section className="hero-section">
      
      <button className="home-button" onClick={goToHome}>
        Главная
      </button>
      
      <a href={`tel:${phoneNumber}`} className="hero-phone">
        <span className="hero-phone-text">{phoneNumber}</span>
      </a>

      <div className="slider-container">
        {slides.map((slide, index) => (
          <div
            key={index}
            className={`slide ${index === currentSlide ? 'active' : ''}`}
            style={{ 
              backgroundImage: `url(${slide.image})`,
              backgroundSize: 'cover',
              backgroundPosition: 'center'
            }}
          />
        ))}
        
        <div className="hero-overlay"></div>
        
        <button className="slider-arrow prev" onClick={prevSlide}>
          ‹
        </button>
        <button className="slider-arrow next" onClick={nextSlide}>
          ›
        </button>
        
        <div className="slider-dots">
          {slides.map((_, index) => (
            <button
              key={index}
              className={`dot ${index === currentSlide ? 'active' : ''}`}
              onClick={() => goToSlide(index)}
            />
          ))}
        </div>
      </div>

      {/* ТЕКСТ ПОВЕРХ СЛАЙДЕРА*/}
      <div className="hero-content">
        <h1>3D печать бетоном</h1>
        <p className="subtitle">Малых архитектурных форм</p>
        <p className="description">Моделируем, печатаем, доставляем</p>
      </div>

      {/* Кнопка "Каталог" */}
      <button className="catalog-button" onClick={onCatalogClick}>
        Каталог
        <span className="arrow-down">↓</span>
      </button>
    </section>
  );
};

export default HeroSection;