import React, { useState } from 'react';
import './Configurator.css';

const colorImages = {
  base: process.env.PUBLIC_URL + '/images/products/bed-big/base.png',
  white: process.env.PUBLIC_URL + '/images/products/bed-big/white.png',
  black: process.env.PUBLIC_URL + '/images/products/bed-big/black.png',
  blue: process.env.PUBLIC_URL + '/images/products/bed-big//blue.png',
  brown: process.env.PUBLIC_URL + '/images/products/bed-big//brown.png',
  pink: process.env.PUBLIC_URL + '/images/products/bed-big//pink.png',
  red: process.env.PUBLIC_URL + '/images/products/bed-big//red.png',
  green: process.env.PUBLIC_URL + '/images/products/bed-big//green.png',
  yellow: process.env.PUBLIC_URL + '/images/products/bed-big//yellow.png',
  lightpink: process.env.PUBLIC_URL + '/images/products/bed-big//light-pink.png'
};

const THREE_D_VIEWER_URL = 'https://cdn.soft8soft.ru/AROAJSY2GOEHMOFUVPIOE:b3d138bc39/Beton-Config/Beton-Config.html';

const ConfiguratorBigBed = () => {
  const [color, setColor] = useState('base');
  const [surface, setSurface] = useState('ribbed');
  const [show3D, setShow3D] = useState(false);


  const PRICES = {
    basePrice: 8000,
    colorWhite: 1000,
    colorOther: 2000,
    plastered: 1500,
  };

  const WEIGHT = {
    base: 100,
    plasteredBonus: 50,
  };

  const SIZES = {
    external: '120х50х20 см',
    internal: '110х40х20 см',
  };


  const getColorPrice = (selectedColor) => {
    if (selectedColor === 'base') return 0;
    if (selectedColor === 'white') return PRICES.colorWhite;
    return PRICES.colorOther;
  };

  const calculatePrice = () => {
    let price = PRICES.basePrice;
    price += getColorPrice(color);
    if (surface === 'plastered') price += PRICES.plastered;
    return Math.round(price);
  };

  const totalPrice = calculatePrice();

  const generateSku = () => {
    const colorCode = color.substring(0, 2).toUpperCase();
    const surfaceCode = surface === 'ribbed' ? 'R' : 'P';
    return `BETON-${colorCode}-${surfaceCode}`;
  };

  const calculateWeight = () => {
    let weight = WEIGHT.base;
    if (surface === 'plastered') {
      weight += WEIGHT.plasteredBonus;
    }
    return weight.toFixed(1);
  };

  const toggle3D = () => {
    setShow3D(!show3D);
  };

  const currentImage = colorImages[color] || colorImages.base;

  const getColorName = (colorKey) => {
    const names = {
      base: 'Базовый',
      white: 'Белый',
      black: 'Черный',
      blue: 'Синий',
      brown: 'Коричневый',
      pink: 'Розовый',
      red: 'Красный',
      green: 'Зеленый',
      yellow: 'Желтый',
      lightpink: 'Светло-розовый'
    };
    return names[colorKey] || colorKey;
  };

  const isBaseColor = color === 'base';

  return (
    <div className="configurator-container">
      <div className="product-card">
        {/* Левая часть - фото */}
        <div className="product-image-wrapper">
          <img src={currentImage} alt={`Бетонное изделие, цвет: ${color}`} className="product-image" />
          <button className="btn-3d" onClick={toggle3D}>
            🎮 3D
          </button>
        </div>

        {/* 3D режим */}
        {show3D && (
          <div className="three-d-modal">
            <div className="three-d-content">
              <button className="close-3d" onClick={toggle3D}>✕</button>
              <iframe
                src={THREE_D_VIEWER_URL}
                title="3D просмотр"
                className="three-d-frame"
                allowFullScreen
              />
            </div>
          </div>
        )}

        {/* Правая часть - конфигуратор */}
        <div className="configurator-panel">
          <h2>Бетонная грядка 120х50х20</h2>
          <h3>Конфигуратор</h3>

          {/* Цвет */}
          <div className="config-group">
            <label>1. Выберите цвет</label>
            <div className="color-picker">
              {Object.keys(colorImages).map((c) => (
                <button
                  key={c}
                  className={`color-btn ${color === c ? 'active' : ''}`}
                  style={{ 
                    backgroundColor: c === 'base' ? '#b0b0b0' : c,
                    border: color === c ? '3px solid #1a1a2e' : '3px solid #dee2e6'
                  }}
                  onClick={() => setColor(c)}
                  title={`${getColorName(c)}${c !== 'base' ? ` (+${getColorPrice(c)} ₽)` : ''}`}
                />
              ))}
            </div>
            <div className="color-info">
              <span>Выбран: <strong>{getColorName(color)}</strong></span>
            </div>
          </div>

          {/* Фактура */}
          <div className="config-group">
            <label>2. Фактура поверхности</label>
            <div className="option-group">
              <button
                className={`option-btn ${surface === 'ribbed' ? 'active' : ''}`}
                onClick={() => setSurface('ribbed')}
              >
                Рифленая
              </button>
              <button
                className={`option-btn ${surface === 'plastered' ? 'active' : ''}`}
                onClick={() => setSurface('plastered')}
              >
                Оштукатуренная
              </button>
            </div>
            {/* Надпись при выборе оштукатуренной - без рамки */}
            {surface === 'plastered' && (
              <div className="surface-notice">
                Оштукатуренная поверхность увеличивает вес на {WEIGHT.plasteredBonus} кг
              </div>
            )}
          </div>

          {/* Цена в конфигураторе */}
          <div className="config-price">
            <span>Цена:</span> {totalPrice} ₽
          </div>
        </div>
      </div>

      {/* Описание товара - снизу, без рамок */}
      <div className="product-description">
        <div className="details-row">
          <span className="label">Цена:</span>
          <span className="value">{totalPrice} ₽</span>
        </div>
        <div className="details-row">
          <span className="label">Название:</span>
          <span className="value">Бетонная грядка</span>
        </div>
        <div className="details-row">
          <span className="label">Цвет:</span>
          <span className="value">{getColorName(color)}</span>
        </div>
        <div className="details-row">
          <span className="label">Размер внешний:</span>
          <span className="value">{SIZES.external}</span>
        </div>
        <div className="details-row">
          <span className="label">Размер внутренний:</span>
          <span className="value">{SIZES.internal}</span>
        </div>
        <div className="details-row">
          <span className="label">Вес:</span>
          <span className="value">{calculateWeight()} кг</span>
        </div>
        <div className="details-row">
          <span className="label">Фактура:</span>
          <span className="value">{surface === 'ribbed' ? 'Рифленая' : 'Оштукатуренная'}</span>
        </div>
        <div className="details-row">
          <span className="label">Артикул:</span>
          <span className="value">{generateSku()}</span>
        </div>
      </div>
    </div>
  );
};

export default ConfiguratorBigBed;