import React, { useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet';
import { findProductBySlug } from '../data/products';

import ConfiguratorBigBed from './configurators/ConfiguratorBigBed';
import ConfiguratorSmallBed from './configurators/ConfiguratorSmallBed';

const configurators = {
  'BigBed': ConfiguratorBigBed,
  'SmallBed': ConfiguratorSmallBed,
};

const ProductPage = () => {
  const { slug } = useParams();
  const navigate = useNavigate();
  
  const product = findProductBySlug(slug);

  useEffect(() => {
    if (!product) {
      navigate('/catalog', { replace: true });
    }
  }, [product, navigate]);

  // Возврат к списку товаров (не в каталог!)
  const goBackToProducts = () => {
    navigate('/catalog', { replace: true });
    // Прокручиваем к каталогу после перехода
    setTimeout(() => {
      const catalogElement = document.getElementById('catalog');
      if (catalogElement) {
        catalogElement.scrollIntoView({ behavior: 'smooth' });
      }
    }, 100);
  };

  if (!product) {
    return null;
  }

  const ConfiguratorComponent = configurators[product.configurator];
  const meta = product.meta || {};

  return (
    <>
      <Helmet>
        <title>{meta.title || product.name}</title>
        <meta name="description" content={meta.description || product.description} />
        <meta name="keywords" content={meta.keywords || ''} />
        <meta property="og:title" content={meta.title || product.name} />
        <meta property="og:description" content={meta.description || product.description} />
        <meta property="og:image" content={product.image} />
        <meta property="og:url" content={`https://betonprint.ru/product/${slug}`} />
        <link rel="canonical" href={`https://betonprint.ru/product/${slug}`} />
      </Helmet>

      <div className="product-page-wrapper">
        <button className="back-button" onClick={goBackToProducts}>
          <span className="back-icon">←</span>
          Назад к товарам
        </button>

        {ConfiguratorComponent ? (
          <ConfiguratorComponent />
        ) : (
          <div className="configurator-placeholder">
            <h2>{product.name}</h2>
            <p>{product.description}</p>
            <p>Конфигуратор для этого товара в разработке</p>
          </div>
        )}
      </div>
    </>
  );
};

export default ProductPage;