import React, { useState, useRef } from 'react';
import emailjs from '@emailjs/browser';
import './ContactForm.css';

const ContactForm = () => {
  const form = useRef();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSent, setIsSent] = useState(false);
  const [error, setError] = useState('');

  const SERVICE_ID = 'service_qt2t3n4';
  const TEMPLATE_ID = 'template_eo615xm';
  const PUBLIC_KEY = 'nRR3TmWUoGrqm4rcH';

  const sendEmail = (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');

    const formData = new FormData(form.current);
    formData.append('timestamp', new Date().toLocaleString('ru-RU'));

    emailjs
      .sendForm(SERVICE_ID, TEMPLATE_ID, form.current, PUBLIC_KEY)
      .then(
        (result) => {
          console.log('✅ Письмо отправлено:', result.text);
          setIsSent(true);
          setIsSubmitting(false);
          form.current.reset();
        },
        (error) => {
          console.error('❌ Ошибка:', error.text);
          setError('Произошла ошибка при отправке. Попробуйте позже.');
          setIsSubmitting(false);
        }
      );
  };

  if (isSent) {
    return (
      <section className="contact-form-section">
        <div className="form-success">
          <div className="success-icon">✅</div>
          <h2>Сообщение отправлено!</h2>
          <p>Мы свяжемся с вами в ближайшее время.</p>
          <button className="success-button" onClick={() => setIsSent(false)}>
            Отправить ещё
          </button>
        </div>
      </section>
    );
  }

  return (
    <section className="contact-form-section">
      <h2>Обратная связь</h2>
      <p className="form-subtitle">Оставьте свои контакты и мы свяжемся с вами</p>

      <form ref={form} onSubmit={sendEmail} className="contact-form">
        <div className="form-group">
          <label htmlFor="email">Email *</label>
          <input
            type="email"
            id="email"
            name="email"
            placeholder="your@email.com"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="phone">Телефон *</label>
          <input
            type="tel"
            id="phone"
            name="phone"
            placeholder="+7 (999) 123-45-67"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="message">Ваше сообщение *</label>
          <textarea
            id="message"
            name="message"
            placeholder="Опишите ваш вопрос или заказ..."
            rows="5"
            required
          />
        </div>

        {error && <div className="form-error">{error}</div>}

        <button 
          type="submit" 
          className="submit-button"
          disabled={isSubmitting}
        >
          {isSubmitting ? (
            <>
              <span className="spinner"></span>
              Отправка...
            </>
          ) : (
            'Отправить'
          )}
        </button>
      </form>
    </section>
  );
};

export default ContactForm;