export const findProductBySlug = (slug) => {
  for (const categoryId in products) {
    const found = products[categoryId].find(p => p.slug === slug);
    if (found) return found;
  }
  return null;
};

export const getAllProducts = () => {
  const all = [];
  for (const categoryId in products) {
    all.push(...products[categoryId]);
  }
  return all;
};